<template>
  <div class="profile">
    <ProfileHeaderModeration
      title="Добавление данных пользователя"
      :uniqueCode="publication?.id"
      :phone="publication?.phone || '+7 (000) 000-00-00'"
      :address="
        publication?.place_inspection ||
        'Ростовская область; Ростов-на-Дону; Ворошиловский р-н'
      "
      :date="publication?.updated_at"
      :moderator="publication?.username"
      :backIcon="backIcon"
      :goBack="goBack"
    />

    <div class="profile__wrapper">
      <div class="violation-content">
        <div class="violation-form">
          <h3 class="violation-form__title">
            Выберите контент, нарушающий правила сервиса и укажите причину:
          </h3>

          <!-- Заголовок / описание -->
          <div class="violation-block">
            <div class="violation-block__info">
              <CheckboxUI v-model="userViolation.enabled" />
              <p class="violation-block__title">{{ userViolation.label }}</p>
            </div>
            <p class="violation-block__text">{{ userViolation.content }}</p>
            <div class="violation-block__dropdown" v-if="userViolation.enabled">
              <AdsDropdown
                :options="dropdownOptions"
                placeholder="Выберите причину"
                @updateSort="(val) => (userViolation.reason = val)"
              />
            </div>
          </div>

          <!-- Фото пользователя -->
          <div class="photo-grid">
            <div class="photo-block">
              <img
                :src="userPhotoViolation.url || avatarPlaceholder"
                class="photo-block__img"
              />

              <div class="photo-block__checkbox">
                <CheckboxUI v-model="userPhotoViolation.enabled" />
              </div>

              <div
                class="photo-block__dropdown"
                v-if="userPhotoViolation.enabled"
              >
                <AdsDropdown
                  :options="dropdownOptions"
                  placeholder="Выберите причину"
                  @updateSort="(val) => (userPhotoViolation.reason = val)"
                />
              </div>
            </div>
          </div>
        </div>
        <div class="violation-form__actions">
          <button @click="approvePublication" class="btn approve">
            Разрешить
          </button>
          <button @click="rejectPublication" class="btn reject">
            Отклонить
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { getUserOtherInfo } from '@/services/apiClient';
import { getImageUrl } from '@/services/imageUtils';
import { updateAction } from '@/services/apiClient';
import backIcon from '@/assets/icons/back-wide.svg';
import avatarPlaceholder from '@/assets/icons/avatar-revers.svg';

import ProfileHeaderModeration from '@/components/UI/CustomProfileHeaderModeration.vue';
import CheckboxUI from '@/components/UI/CheckboxUINEW.vue';
import AdsDropdown from '@/components/AdsDropdown.vue';

const route = useRoute();
const router = useRouter();
const publication = ref(null);
const loading = ref(true);

const dropdownOptions = [
  { label: 'Нарушение законодательства (П. 2)', value: 'law_violation' },
  {
    label: 'Нарушение правил сервиса (П. 3)',
    value: 'service_rules_violation',
  },
  { label: 'Грубая лексика (П. 4)', value: 'offensive_language' },
  { label: 'Недостоверные данные (П. 5)', value: 'false_information' },
  { label: 'Мошенничество (П. 6)', value: 'fraud' },
  { label: 'Порнография (П. 7)', value: 'pornography' },
  { label: 'Другое', value: 'other' },
];

const userViolation = ref({
  label: 'Имя пользователя',
  enabled: false,
  reason: null,
  get content() {
    return publication.value?.username || 'Нe указано';
  },
});

const userPhotoViolation = ref({
  id: null,
  url: avatarPlaceholder,
  enabled: false,
  reason: null,
});

const collectAdminComment = () => {
  const fieldsComment = {};

  if (userViolation.value.enabled && userViolation.value.reason) {
    fieldsComment.username = userViolation.value.reason;
  }

  if (userPhotoViolation.value.enabled && userPhotoViolation.value.reason) {
    fieldsComment[`photo_${userPhotoViolation.value.id}`] =
      userPhotoViolation.value.reason;
  }

  return fieldsComment;
};

const approvePublication = async () => {
  const formData = {
    is_cancelled: 0,
  };
  // нужен ли этот лог в проекте
  console.log('APPROVED DATA:', formData);
  const type = 'users';
  await updateAction(route.params.id, formData, type);
};

const rejectPublication = async () => {
  const formData = {
    is_cancelled: 1,
    admin_comment: {
      fields_comment: collectAdminComment(),
    },
  };
  // нужен ли этот лог в проекте
  console.log('REJECTED DATA:', formData);
  const type = 'users';
  await updateAction(route.params.id, formData, type);
};

const fetchPublicationData = async () => {
  try {
    const response = await getUserOtherInfo(route.params.id);
    publication.value = response;

    if (response.photo && response.photo.id) {
      userPhotoViolation.value = {
        id: response.photo.id,
        title: response.photo.title,
        url: getImageUrl(response.photo.arr_title_size?.default),
        enabled: false,
        reason: null,
      };
    } else {
      userPhotoViolation.value = {
        id: null,
        url: avatarPlaceholder,
        enabled: false,
        reason: null,
      };
    }
  } catch (error) {
    console.error('Ошибка при получении данных объявления:', error);
    publication.value = null;
  } finally {
    loading.value = false;
  }
};

const goBack = () => {
  router.back();
};

onMounted(fetchPublicationData);
</script>

